<!DOCTYPE html>
<html>
    <head>
        <title>Error 404 | We can't find that page</title>
        <link href="{{url('theme_frontend/css/bootstrap.css')}}" rel="stylesheet" media="screen">
        <link href="https://fonts.googleapis.com/css?family=Lato:100" rel="stylesheet" type="text/css">

        <style>
            body { background-image: url(data:image/png;base64,);}
            .error-template {padding: 40px 15px;text-align: center;}
            .error-actions {margin-top:15px;margin-bottom:15px;}
            .error-actions .btn { margin-right:10px; }
            .image-center {
                display: block;
                margin-left: auto;
                margin-right: auto;
            }
        </style>
    </head>
    <body>
        <div class="container">
            <div class="row">
                <div class="col-md-12">
                    <div class="error-template">
                        <h1>Error 404 | That's an error.</h1>
                        <h2>The requested URL was not found on this server. That's all we know.</h2>
                    </div>
                </div>
            </div>
        </div>
    </body>
</html>
